normal_mapping.frag<pre><code>in vec2 TexCoords;
in mat3 TBN; // Vertex shader'dan gelen TBN matrisi

uniform sampler2D normalMap;

void main()
{
    // Normal haritasından oku ve [-1, 1] aralığına aç
    vec3 normal = texture(normalMap, TexCoords).rgb;
    normal = normalize(normal * 2.0 - 1.0);   

    // Tanjant uzayından dünya uzayına dönüştür!
    normal = normalize(TBN * normal);

    // ... normal ile aydınlatma hesapları ...
}
</code></pre> <p>Sonuç: Düz bir yüzey, ışık hareket ettikçe sanki gerçek oyuklara ve taş çıkıntılarına sahipmiş gibi büyüleyici bir şekilde parlar!</p>

G-Buffer Kurulumu<pre><code>unsigned int gBuffer;
glGenFramebuffers(1, &amp;gBuffer);
glBindFramebuffer(GL_FRAMEBUFFER, gBuffer);

unsigned int gPosition, gNormal, gAlbedoSpec;

// 1. Konum Dokusu
glGenTextures(1, &amp;gPosition);
glBindTexture(GL_TEXTURE_2D, gPosition);
glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA16F, SCR_WIDTH, SCR_HEIGHT, 0, GL_RGBA, GL_FLOAT, NULL);
glFramebufferTexture2D(GL_FRAMEBUFFER, GL_COLOR_ATTACHMENT0, GL_TEXTURE_2D, gPosition, 0);

// 2. Normal Dokusu
glGenTextures(1, &amp;gNormal);
glBindTexture(GL_TEXTURE_2D, gNormal);
glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA16F, SCR_WIDTH, SCR_HEIGHT, 0, GL_RGBA, GL_FLOAT, NULL);
glFramebufferTexture2D(GL_FRAMEBUFFER, GL_COLOR_ATTACHMENT1, GL_TEXTURE_2D, gNormal, 0);

// 3. Renk + Parlaklık Dokusu
glGenTextures(1, &amp;gAlbedoSpec);
glBindTexture(GL_TEXTURE_2D, gAlbedoSpec);
glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, SCR_WIDTH, SCR_HEIGHT, 0, GL_RGBA, GL_UNSIGNED_BYTE, NULL);
glFramebufferTexture2D(GL_FRAMEBUFFER, GL_COLOR_ATTACHMENT2, GL_TEXTURE_2D, gAlbedoSpec, 0);

// Çizim hedeflerini bildir
unsigned int attachments[3] = { GL_COLOR_ATTACHMENT0, GL_COLOR_ATTACHMENT1, GL_COLOR_ATTACHMENT2 };
glDrawBuffers(3, attachments);
</code></pre>

deferred_lighting.frag<pre><code>#version 330 core
out vec4 FragColor;
in vec2 TexCoords;

uniform sampler2D gPosition;
uniform sampler2D gNormal;
uniform sampler2D gAlbedoSpec;

struct Light {
    vec3 Position;
    vec3 Color;
    float Linear;
    float Quadratic;
};
const int NR_LIGHTS = 32;
uniform Light lights[NR_LIGHTS];
uniform vec3 viewPos;

void main()
{             
    vec3 FragPos = texture(gPosition, TexCoords).rgb;
    vec3 Normal = texture(gNormal, TexCoords).rgb;
    vec3 Diffuse = texture(gAlbedoSpec, TexCoords).rgb;
    float Specular = texture(gAlbedoSpec, TexCoords).a;

    vec3 lighting = Diffuse * 0.1; // Ambient
    vec3 viewDir = normalize(viewPos - FragPos);

    for(int i = 0; i &lt; NR_LIGHTS; ++i)
    {
        // Mesafe zayıflaması (attenuation)
        float distance = length(lights[i].Position - FragPos);
        float attenuation = 1.0 / (1.0 + lights[i].Linear * distance + lights[i].Quadratic * distance * distance);

        // Difüz
        vec3 lightDir = normalize(lights[i].Position - FragPos);
        vec3 diffuse = max(dot(Normal, lightDir), 0.0) * Diffuse * lights[i].Color;

        // Speküler (Blinn-Phong)
        vec3 halfwayDir = normalize(lightDir + viewDir);  
        float spec = pow(max(dot(Normal, halfwayDir), 0.0), 16.0);
        vec3 specular = lights[i].Color * spec * Specular;

        lighting += (diffuse + specular) * attenuation;
    }
    FragColor = vec4(lighting, 1.0);
}
</code></pre> <p>[!WARNING] Deferred Shading Dezavantajları: - Çok fazla bellek ve bant genişliği harcar (G-Buffer dokuları ağırdır). - Şeffaflık (Blending) doğrudan uygulanamaz (şeffaf nesneler en son Forward Shading ile çizilmelidir). - Donanımsal MSAA (Multi-Sample Anti-Aliasing) doğrudan çalışmaz (FXAA veya TAA gibi post-process AA gerektirir).</p>

ssao.frag<pre><code>#version 330 core
out float FragColor;
in vec2 TexCoords;

uniform sampler2D gPosition;
uniform sampler2D gNormal;
uniform sampler2D texNoise;

uniform vec3 samples[64];
uniform mat4 projection;

const vec2 noiseScale = vec2(800.0/4.0, 600.0/4.0); 

void main()
{
    vec3 fragPos = texture(gPosition, TexCoords).xyz;
    vec3 normal = normalize(texture(gNormal, TexCoords).rgb);
    vec3 randomVec = normalize(texture(texNoise, TexCoords * noiseScale).xyz);

    // Teğet uzay oluştur (Gram-Schmidt)
    vec3 tangent = normalize(randomVec - normal * dot(randomVec, normal));
    vec3 bitangent = cross(normal, tangent);
    mat3 TBN = mat3(tangent, bitangent, normal);

    float occlusion = 0.0;
    for(int i = 0; i &lt; 64; ++i)
    {
        // Örnek noktasını dünya/görüş uzayına al
        vec3 samplePos = TBN * samples[i]; 
        samplePos = fragPos + samplePos * 0.5; // 0.5 yarıçap

        // Ekran koordinatlarına projekte et
        vec4 offset = vec4(samplePos, 1.0);
        offset = projection * offset;
        offset.xyz /= offset.w;
        offset.xyz = offset.xyz * 0.5 + 0.5;

        float sampleDepth = texture(gPosition, offset.xy).z;

        // Aralık kontrolü ve tıkanma hesabı
        float rangeCheck = smoothstep(0.0, 1.0, 0.5 / abs(fragPos.z - sampleDepth));
        occlusion += (sampleDepth &gt;= samplePos.z + 0.025 ? 1.0 : 0.0) * rangeCheck;           
    }
    occlusion = 1.0 - (occlusion / 64.0);
    FragColor = occlusion;
}
</code></pre> <p>Son adımda oluşan gürültüyü gidermek için \(4 \times 4\) basit bir bulanıklık (blur) filtresi uygulanır. Ortam aydınlatmasını bu faktörle çarptığınızda (<code>ambient * ssao</code>), sahnedeki tüm nesnelerin köşe ve çatlakları adeta hayat bulur!</p>
